import{_ as s,o as a,c as t,a as p}from"./app-215c512d.js";const o={};function c(e,n){return a(),t("div",null,n[0]||(n[0]=[p(`<h2 id="cornutils-表达式动态生成" tabindex="-1"><a class="header-anchor" href="#cornutils-表达式动态生成" aria-hidden="true">#</a> cornUtils 表达式动态生成</h2><ul><li>CronUtils 提供了 <code>CronBuilder</code> 类，可以灵活地构建 Cron 表达式。以下是对动态生成 Cron 表达式的详细说明和用法展开。</li></ul><hr><h3 id="_1-cron-表达式的基本结构" tabindex="-1"><a class="header-anchor" href="#_1-cron-表达式的基本结构" aria-hidden="true">#</a> 1. <strong>Cron 表达式的基本结构</strong></h3><p>Cron 表达式通常由多个字段组成，具体取决于使用的格式（如 Quartz、Unix 等）。以下是 Quartz 格式的字段及其含义：</p><div class="language-text" data-ext="text"><pre class="language-text"><code>秒 分 时 日 月 周 [年]
</code></pre></div><ul><li><strong>秒 (0-59)</strong>：表示每分钟的第几秒触发。</li><li><strong>分 (0-59)</strong>：表示每小时的第几分钟触发。</li><li><strong>时 (0-23)</strong>：表示每天的第几小时触发。</li><li><strong>日 (1-31)</strong>：表示每月的第几天触发。</li><li><strong>月 (1-12 或 JAN-DEC)</strong>：表示每年的第几个月触发。</li><li><strong>周 (0-7 或 SUN-SAT, 其中 0 和 7 都表示星期日)</strong>：表示每周的哪一天触发。</li><li><strong>年 (可选)</strong>：表示哪一年触发。</li></ul><p>例如：</p><ul><li><code>0 30 14 * * ?</code>：每天下午 2 点 30 分触发。</li><li><code>0 0/5 * * * ?</code>：每 5 分钟触发一次。</li></ul><hr><h3 id="_2-使用-cronbuilder-动态生成-cron-表达式" tabindex="-1"><a class="header-anchor" href="#_2-使用-cronbuilder-动态生成-cron-表达式" aria-hidden="true">#</a> 2. <strong>使用 CronBuilder 动态生成 Cron 表达式</strong></h3><p>CronUtils 的 <code>CronBuilder</code> 类允许你通过编程方式动态构建 Cron 表达式。每个字段都可以通过工厂方法（如 <code>FieldExpressionFactory</code>）设置具体的值或规则。</p><h4 id="示例代码-动态生成-cron-表达式" tabindex="-1"><a class="header-anchor" href="#示例代码-动态生成-cron-表达式" aria-hidden="true">#</a> 示例代码：动态生成 Cron 表达式</h4><div class="language-java" data-ext="java"><pre class="language-java"><code><span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>builder<span class="token punctuation">.</span></span><span class="token class-name">CronBuilder</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span></span><span class="token class-name">Cron</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span>definition<span class="token punctuation">.</span></span><span class="token class-name">CronDefinition</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span>definition<span class="token punctuation">.</span></span><span class="token class-name">CronDefinitionBuilder</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span>field<span class="token punctuation">.</span>expression<span class="token punctuation">.</span></span><span class="token class-name">FieldExpressionFactory</span></span><span class="token punctuation">;</span>

<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">DynamicCronGeneration</span> <span class="token punctuation">{</span>

    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">void</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> args<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// 定义 Quartz 格式的 Cron</span>
        <span class="token class-name">CronDefinition</span> cronDefinition <span class="token operator">=</span> <span class="token class-name">CronDefinitionBuilder</span><span class="token punctuation">.</span><span class="token function">instanceDefinitionFor</span><span class="token punctuation">(</span><span class="token class-name">CronType</span><span class="token punctuation">.</span><span class="token constant">QUARTZ</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 动态生成 Cron 表达式</span>
        <span class="token class-name">Cron</span> cron <span class="token operator">=</span> <span class="token class-name">CronBuilder</span><span class="token punctuation">.</span><span class="token function">cron</span><span class="token punctuation">(</span>cronDefinition<span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">withSecond</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">)</span>       <span class="token comment">// 秒：0</span>
                <span class="token punctuation">.</span><span class="token function">withMinute</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">every</span><span class="token punctuation">(</span><span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">)</span>    <span class="token comment">// 分：每 5 分钟</span>
                <span class="token punctuation">.</span><span class="token function">withHour</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">between</span><span class="token punctuation">(</span><span class="token number">9</span><span class="token punctuation">,</span> <span class="token number">17</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token comment">// 时：9 点到 17 点之间</span>
                <span class="token punctuation">.</span><span class="token function">withDoM</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">every</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>        <span class="token comment">// 日：每天</span>
                <span class="token punctuation">.</span><span class="token function">withMonth</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">every</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>      <span class="token comment">// 月：每月</span>
                <span class="token punctuation">.</span><span class="token function">withDoW</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">questionMark</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token comment">// 周：不指定</span>
                <span class="token punctuation">.</span><span class="token function">instance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 输出生成的 Cron 表达式</span>
        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;生成的 Cron 表达式: &quot;</span> <span class="token operator">+</span> cron<span class="token punctuation">.</span><span class="token function">asString</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>运行结果：</p><div class="language-text" data-ext="text"><pre class="language-text"><code>生成的 Cron 表达式: 0 0/5 9-17 * * ?
</code></pre></div><hr><h3 id="_3-cronbuilder-的核心方法" tabindex="-1"><a class="header-anchor" href="#_3-cronbuilder-的核心方法" aria-hidden="true">#</a> 3. <strong>CronBuilder 的核心方法</strong></h3><p><code>CronBuilder</code> 提供了一系列方法来设置 Cron 表达式的各个字段。以下是常用的方法及其作用：</p><table><thead><tr><th>方法名</th><th>描述</th></tr></thead><tbody><tr><td><code>withSecond()</code></td><td>设置秒字段。</td></tr><tr><td><code>withMinute()</code></td><td>设置分字段。</td></tr><tr><td><code>withHour()</code></td><td>设置时字段。</td></tr><tr><td><code>withDoM()</code></td><td>设置日期字段（每月的第几天）。</td></tr><tr><td><code>withMonth()</code></td><td>设置月份字段。</td></tr><tr><td><code>withDoW()</code></td><td>设置星期字段（每周的哪一天）。</td></tr><tr><td><code>withYear()</code></td><td>设置年份字段（可选）。</td></tr></tbody></table><p>每个字段可以通过 <code>FieldExpressionFactory</code> 提供的静态方法设置具体的值或规则。</p><hr><h3 id="_4-fieldexpressionfactory-的常用方法" tabindex="-1"><a class="header-anchor" href="#_4-fieldexpressionfactory-的常用方法" aria-hidden="true">#</a> 4. <strong>FieldExpressionFactory 的常用方法</strong></h3><p><code>FieldExpressionFactory</code> 是用于生成字段表达式的工具类，支持多种规则。以下是常用的工厂方法及其作用：</p><table><thead><tr><th>方法名</th><th>描述</th></tr></thead><tbody><tr><td><code>on(value)</code></td><td>指定固定值。例如：<code>FieldExpressionFactory.on(30)</code> 表示固定的 30 分钟。</td></tr><tr><td><code>every()</code></td><td>表示“每一天”、“每一月”等。</td></tr><tr><td><code>every(interval)</code></td><td>表示每隔一段时间。例如：<code>FieldExpressionFactory.every(5)</code> 表示每 5 分钟。</td></tr><tr><td><code>between(start, end)</code></td><td>表示范围。例如：<code>FieldExpressionFactory.between(9, 17)</code> 表示 9 到 17 点之间。</td></tr><tr><td><code>questionMark()</code></td><td>表示不指定（仅适用于日期和星期字段）。</td></tr><tr><td><code>lastDayOfMonth()</code></td><td>表示每月的最后一天。</td></tr><tr><td><code>lastWeekdayOfMonth()</code></td><td>表示每月的最后一个工作日。</td></tr><tr><td><code>nthDayOfWeek(n, day)</code></td><td>表示某个月的第 n 个星期几。例如：<code>FieldExpressionFactory.nthDayOfWeek(2, 1)</code> 表示每个月的第二个星期一。</td></tr></tbody></table><hr><h3 id="_5-动态生成-cron-表达式的应用场景" tabindex="-1"><a class="header-anchor" href="#_5-动态生成-cron-表达式的应用场景" aria-hidden="true">#</a> 5. <strong>动态生成 Cron 表达式的应用场景</strong></h3><h4 id="_1-用户自定义任务调度" tabindex="-1"><a class="header-anchor" href="#_1-用户自定义任务调度" aria-hidden="true">#</a> (1) <strong>用户自定义任务调度</strong></h4><p>假设用户可以通过界面选择任务的执行时间，例如：</p><ul><li>每天上午 9 点到下午 5 点之间，每 10 分钟执行一次。</li><li>每月的最后一天凌晨 0 点执行。</li></ul><p>可以根据用户输入动态生成对应的 Cron 表达式。</p><h4 id="示例代码-根据用户输入生成-cron-表达式" tabindex="-1"><a class="header-anchor" href="#示例代码-根据用户输入生成-cron-表达式" aria-hidden="true">#</a> 示例代码：根据用户输入生成 Cron 表达式</h4><div class="language-java" data-ext="java"><pre class="language-java"><code><span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>builder<span class="token punctuation">.</span></span><span class="token class-name">CronBuilder</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span></span><span class="token class-name">Cron</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span>definition<span class="token punctuation">.</span></span><span class="token class-name">CronDefinition</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span>definition<span class="token punctuation">.</span></span><span class="token class-name">CronDefinitionBuilder</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span>field<span class="token punctuation">.</span>expression<span class="token punctuation">.</span></span><span class="token class-name">FieldExpressionFactory</span></span><span class="token punctuation">;</span>

<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">UserDefinedCron</span> <span class="token punctuation">{</span>

    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">void</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> args<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// 用户输入</span>
        <span class="token keyword">int</span> startHour <span class="token operator">=</span> <span class="token number">9</span><span class="token punctuation">;</span>   <span class="token comment">// 开始时间：9 点</span>
        <span class="token keyword">int</span> endHour <span class="token operator">=</span> <span class="token number">17</span><span class="token punctuation">;</span>    <span class="token comment">// 结束时间：17 点</span>
        <span class="token keyword">int</span> interval <span class="token operator">=</span> <span class="token number">10</span><span class="token punctuation">;</span>   <span class="token comment">// 每 10 分钟</span>

        <span class="token comment">// 定义 Quartz 格式的 Cron</span>
        <span class="token class-name">CronDefinition</span> cronDefinition <span class="token operator">=</span> <span class="token class-name">CronDefinitionBuilder</span><span class="token punctuation">.</span><span class="token function">instanceDefinitionFor</span><span class="token punctuation">(</span><span class="token class-name">CronType</span><span class="token punctuation">.</span><span class="token constant">QUARTZ</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 动态生成 Cron 表达式</span>
        <span class="token class-name">Cron</span> cron <span class="token operator">=</span> <span class="token class-name">CronBuilder</span><span class="token punctuation">.</span><span class="token function">cron</span><span class="token punctuation">(</span>cronDefinition<span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">withSecond</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">)</span>               <span class="token comment">// 秒：0</span>
                <span class="token punctuation">.</span><span class="token function">withMinute</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">every</span><span class="token punctuation">(</span>interval<span class="token punctuation">)</span><span class="token punctuation">)</span>      <span class="token comment">// 分：每 10 分钟</span>
                <span class="token punctuation">.</span><span class="token function">withHour</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">between</span><span class="token punctuation">(</span>startHour<span class="token punctuation">,</span> endHour<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token comment">// 时：9 点到 17 点之间</span>
                <span class="token punctuation">.</span><span class="token function">withDoM</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">every</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>                <span class="token comment">// 日：每天</span>
                <span class="token punctuation">.</span><span class="token function">withMonth</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">every</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>              <span class="token comment">// 月：每月</span>
                <span class="token punctuation">.</span><span class="token function">withDoW</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">questionMark</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>          <span class="token comment">// 周：不指定</span>
                <span class="token punctuation">.</span><span class="token function">instance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 输出生成的 Cron 表达式</span>
        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;生成的 Cron 表达式: &quot;</span> <span class="token operator">+</span> cron<span class="token punctuation">.</span><span class="token function">asString</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>运行结果：</p><div class="language-text" data-ext="text"><pre class="language-text"><code>生成的 Cron 表达式: 0 0/10 9-17 * * ?
</code></pre></div><hr><h4 id="_2-复杂调度规则" tabindex="-1"><a class="header-anchor" href="#_2-复杂调度规则" aria-hidden="true">#</a> (2) <strong>复杂调度规则</strong></h4><p>例如：</p><ul><li>每月的最后一个工作日凌晨 2 点执行。</li><li>每年的 1 月 1 日凌晨 0 点执行。</li></ul><div class="language-java" data-ext="java"><pre class="language-java"><code><span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>builder<span class="token punctuation">.</span></span><span class="token class-name">CronBuilder</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span></span><span class="token class-name">Cron</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span>definition<span class="token punctuation">.</span></span><span class="token class-name">CronDefinition</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span>definition<span class="token punctuation">.</span></span><span class="token class-name">CronDefinitionBuilder</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span>field<span class="token punctuation">.</span>expression<span class="token punctuation">.</span></span><span class="token class-name">FieldExpressionFactory</span></span><span class="token punctuation">;</span>

<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">ComplexCronExample</span> <span class="token punctuation">{</span>

    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">void</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> args<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// 定义 Quartz 格式的 Cron</span>
        <span class="token class-name">CronDefinition</span> cronDefinition <span class="token operator">=</span> <span class="token class-name">CronDefinitionBuilder</span><span class="token punctuation">.</span><span class="token function">instanceDefinitionFor</span><span class="token punctuation">(</span><span class="token class-name">CronType</span><span class="token punctuation">.</span><span class="token constant">QUARTZ</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 每月的最后一个工作日凌晨 2 点</span>
        <span class="token class-name">Cron</span> lastWorkdayOfMonth <span class="token operator">=</span> <span class="token class-name">CronBuilder</span><span class="token punctuation">.</span><span class="token function">cron</span><span class="token punctuation">(</span>cronDefinition<span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">withSecond</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">withMinute</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">withHour</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">withDoM</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">lastWeekdayOfMonth</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">withMonth</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">every</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">withDoW</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">questionMark</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">instance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 每年的 1 月 1 日凌晨 0 点</span>
        <span class="token class-name">Cron</span> newYear <span class="token operator">=</span> <span class="token class-name">CronBuilder</span><span class="token punctuation">.</span><span class="token function">cron</span><span class="token punctuation">(</span>cronDefinition<span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">withSecond</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">withMinute</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">withHour</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">withDoM</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">withMonth</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">withDoW</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">questionMark</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">instance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 输出生成的 Cron 表达式</span>
        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;每月最后一个工作日凌晨 2 点: &quot;</span> <span class="token operator">+</span> lastWorkdayOfMonth<span class="token punctuation">.</span><span class="token function">asString</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;每年 1 月 1 日凌晨 0 点: &quot;</span> <span class="token operator">+</span> newYear<span class="token punctuation">.</span><span class="token function">asString</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>运行结果：</p><div class="language-text" data-ext="text"><pre class="language-text"><code>每月最后一个工作日凌晨 2 点: 0 0 2 LW * ?
每年 1 月 1 日凌晨 0 点: 0 0 0 1 1 ?
</code></pre></div><h3 id="_6-总结" tabindex="-1"><a class="header-anchor" href="#_6-总结" aria-hidden="true">#</a> 6. <strong>总结</strong></h3><ul><li><strong>灵活性</strong>：通过 <code>CronBuilder</code> 和 <code>FieldExpressionFactory</code>，可以灵活地定义各种复杂的调度规则。</li><li><strong>动态生成</strong>：可以根据用户输入或业务逻辑动态生成 Cron 表达式。</li><li><strong>多场景适用</strong>：支持从简单的固定时间调度到复杂的周期性任务调度。</li></ul><h3 id="_7-cron-表达式的含义" tabindex="-1"><a class="header-anchor" href="#_7-cron-表达式的含义" aria-hidden="true">#</a> 7. <strong>Cron 表达式的含义</strong></h3><p>Cron 表达式 <code>0 15 10 ? * 2</code> 的字段解释如下（Quartz 格式）：</p><table><thead><tr><th>字段</th><th>含义</th><th>值范围</th><th>示例值</th></tr></thead><tbody><tr><td>秒</td><td>每分钟的第几秒触发</td><td>0-59</td><td>0</td></tr><tr><td>分</td><td>每小时的第几分钟触发</td><td>0-59</td><td>15</td></tr><tr><td>时</td><td>每天的第几小时触发</td><td>0-23</td><td>10</td></tr><tr><td>日</td><td>每月的第几天触发</td><td>1-31 或 <code>?</code></td><td><code>?</code></td></tr><tr><td>月</td><td>每年的第几个月触发</td><td>1-12 或 <code>*</code></td><td><code>*</code></td></tr><tr><td>周</td><td>每周的哪一天触发</td><td>0-7 或 <code>?</code></td><td>2</td></tr></tbody></table><p><strong>解析：</strong></p><ul><li><code>0</code>：表示每分钟的第 0 秒触发。</li><li><code>15</code>：表示每小时的第 15 分钟触发。</li><li><code>10</code>：表示每天的第 10 小时触发。</li><li><code>?</code>：表示“日”字段不指定（与“周”字段互斥）。</li><li><code>*</code>：表示每月都触发。</li><li><code>2</code>：表示每周的星期一触发（在 Quartz 中，<code>2</code> 表示星期一，<code>1</code> 表示星期日，<code>7</code> 也表示星期日）。</li></ul><p>因此，这个 Cron 表达式的含义是：</p><blockquote><p><strong>每周一上午 10 点 15 分触发任务。</strong></p></blockquote><ul><li>在 <code>CronUtils</code> 的最新版本中，<code>FieldExpressionFactory</code> 确实没有无参数的 <code>every()</code> 方法。这是一个重要的细节，可能是由于库的更新或设计变更导致的。</li></ul><p>在这种情况下，我们需要使用其他方法来实现类似“每一天”、“每一月”的功能。以下是详细的解决方案和替代方法。</p><hr><h3 id="_1-问题分析" tabindex="-1"><a class="header-anchor" href="#_1-问题分析" aria-hidden="true">#</a> 1. <strong>问题分析</strong></h3><h4 id="_1-为什么没有无参数的-every-方法" tabindex="-1"><a class="header-anchor" href="#_1-为什么没有无参数的-every-方法" aria-hidden="true">#</a> (1) <strong>为什么没有无参数的 <code>every()</code> 方法？</strong></h4><p>在 <code>CronUtils</code> 的设计中，字段表达式的生成是通过具体的规则来实现的。对于日期（<code>DoM</code>）和月份（<code>Month</code>）字段，“每一天”或“每一月”的逻辑可以通过以下方式实现：</p><ul><li>使用 <code>FieldExpressionFactory.every(interval)</code> 并指定间隔为 1。</li><li>或者直接使用 <code>FieldExpressionFactory.on(&quot;*&quot;)</code> 表示“所有值”。</li></ul><h4 id="_2-如何替代无参数的-every-方法" tabindex="-1"><a class="header-anchor" href="#_2-如何替代无参数的-every-方法" aria-hidden="true">#</a> (2) <strong>如何替代无参数的 <code>every()</code> 方法？</strong></h4><p>对于日期（<code>DoM</code>）、月份（<code>Month</code>）等字段，可以使用以下方法：</p><ul><li><code>FieldExpressionFactory.on(&quot;*&quot;)</code>：表示“所有值”，等价于无参数的 <code>every()</code>。</li><li><code>FieldExpressionFactory.between(start, end)</code>：表示范围，例如“每月 1 到 31 日”或“每年 1 到 12 月”。</li></ul><hr><h3 id="_2-解决方案" tabindex="-1"><a class="header-anchor" href="#_2-解决方案" aria-hidden="true">#</a> 2. <strong>解决方案</strong></h3><p>以下是针对不同字段的正确用法：</p><h4 id="_1-日期-dom-字段" tabindex="-1"><a class="header-anchor" href="#_1-日期-dom-字段" aria-hidden="true">#</a> (1) <strong>日期（<code>DoM</code>）字段</strong></h4><p>如果需要表示“每天”，可以使用 <code>FieldExpressionFactory.on(&quot;*&quot;)</code> 或 <code>FieldExpressionFactory.between(1, 31)</code>。</p><div class="language-java" data-ext="java"><pre class="language-java"><code><span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>builder<span class="token punctuation">.</span></span><span class="token class-name">CronBuilder</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span></span><span class="token class-name">Cron</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span>definition<span class="token punctuation">.</span></span><span class="token class-name">CronDefinition</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span>definition<span class="token punctuation">.</span></span><span class="token class-name">CronDefinitionBuilder</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span>field<span class="token punctuation">.</span>expression<span class="token punctuation">.</span></span><span class="token class-name">FieldExpressionFactory</span></span><span class="token punctuation">;</span>

<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">CronExample</span> <span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">void</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> args<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// 定义 Quartz 格式的 Cron</span>
        <span class="token class-name">CronDefinition</span> cronDefinition <span class="token operator">=</span> <span class="token class-name">CronDefinitionBuilder</span><span class="token punctuation">.</span><span class="token function">instanceDefinitionFor</span><span class="token punctuation">(</span><span class="token class-name">CronType</span><span class="token punctuation">.</span><span class="token constant">QUARTZ</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 动态生成 Cron 表达式</span>
        <span class="token class-name">Cron</span> cron <span class="token operator">=</span> <span class="token class-name">CronBuilder</span><span class="token punctuation">.</span><span class="token function">cron</span><span class="token punctuation">(</span>cronDefinition<span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">withSecond</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">)</span>       <span class="token comment">// 秒：0</span>
                <span class="token punctuation">.</span><span class="token function">withMinute</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">every</span><span class="token punctuation">(</span><span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">)</span>    <span class="token comment">// 分：每 5 分钟</span>
                <span class="token punctuation">.</span><span class="token function">withHour</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">between</span><span class="token punctuation">(</span><span class="token number">9</span><span class="token punctuation">,</span> <span class="token number">17</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token comment">// 时：9 点到 17 点之间</span>
                <span class="token punctuation">.</span><span class="token function">withDoM</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string">&quot;*&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span>        <span class="token comment">// 日：每天</span>
                <span class="token punctuation">.</span><span class="token function">withMonth</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string">&quot;*&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span>      <span class="token comment">// 月：每月</span>
                <span class="token punctuation">.</span><span class="token function">withDoW</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">questionMark</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token comment">// 周：不指定</span>
                <span class="token punctuation">.</span><span class="token function">instance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 输出生成的 Cron 表达式</span>
        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;生成的 Cron 表达式: &quot;</span> <span class="token operator">+</span> cron<span class="token punctuation">.</span><span class="token function">asString</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>运行结果：</p><div class="language-text" data-ext="text"><pre class="language-text"><code>生成的 Cron 表达式: 0 0/5 9-17 * * ?
</code></pre></div><h4 id="_2-月份-month-字段" tabindex="-1"><a class="header-anchor" href="#_2-月份-month-字段" aria-hidden="true">#</a> (2) <strong>月份（<code>Month</code>）字段</strong></h4><p>如果需要表示“每月”，可以使用 <code>FieldExpressionFactory.on(&quot;*&quot;)</code> 或 <code>FieldExpressionFactory.between(1, 12)</code>。</p><div class="language-java" data-ext="java"><pre class="language-java"><code><span class="token punctuation">.</span><span class="token function">withMonth</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string">&quot;*&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token comment">// 每月</span>
</code></pre></div><h4 id="_3-秒、分、时字段" tabindex="-1"><a class="header-anchor" href="#_3-秒、分、时字段" aria-hidden="true">#</a> (3) <strong>秒、分、时字段</strong></h4><p>对于秒、分、时字段，仍然需要使用带参数的 <code>every(interval)</code> 方法。</p><div class="language-java" data-ext="java"><pre class="language-java"><code><span class="token punctuation">.</span><span class="token function">withSecond</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">every</span><span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token comment">// 每 10 秒触发一次</span>
<span class="token punctuation">.</span><span class="token function">withMinute</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">every</span><span class="token punctuation">(</span><span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">)</span>  <span class="token comment">// 每 5 分钟触发一次</span>
<span class="token punctuation">.</span><span class="token function">withHour</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">every</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">)</span>    <span class="token comment">// 每 2 小时触发一次</span>
</code></pre></div><hr><h3 id="_3-完整示例代码" tabindex="-1"><a class="header-anchor" href="#_3-完整示例代码" aria-hidden="true">#</a> 3. <strong>完整示例代码</strong></h3><p>以下是一个完整的动态生成 Cron 表达式的示例：</p><div class="language-java" data-ext="java"><pre class="language-java"><code><span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>builder<span class="token punctuation">.</span></span><span class="token class-name">CronBuilder</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span></span><span class="token class-name">Cron</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span>definition<span class="token punctuation">.</span></span><span class="token class-name">CronDefinition</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span>definition<span class="token punctuation">.</span></span><span class="token class-name">CronDefinitionBuilder</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span>field<span class="token punctuation">.</span>expression<span class="token punctuation">.</span></span><span class="token class-name">FieldExpressionFactory</span></span><span class="token punctuation">;</span>

<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">DynamicCronGeneration</span> <span class="token punctuation">{</span>

    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">void</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> args<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// 定义 Quartz 格式的 Cron</span>
        <span class="token class-name">CronDefinition</span> cronDefinition <span class="token operator">=</span> <span class="token class-name">CronDefinitionBuilder</span><span class="token punctuation">.</span><span class="token function">instanceDefinitionFor</span><span class="token punctuation">(</span><span class="token class-name">CronType</span><span class="token punctuation">.</span><span class="token constant">QUARTZ</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 动态生成 Cron 表达式</span>
        <span class="token class-name">Cron</span> cron <span class="token operator">=</span> <span class="token class-name">CronBuilder</span><span class="token punctuation">.</span><span class="token function">cron</span><span class="token punctuation">(</span>cronDefinition<span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">withSecond</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">)</span>               <span class="token comment">// 秒：0</span>
                <span class="token punctuation">.</span><span class="token function">withMinute</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">every</span><span class="token punctuation">(</span><span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">)</span>            <span class="token comment">// 分：每 5 分钟</span>
                <span class="token punctuation">.</span><span class="token function">withHour</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">between</span><span class="token punctuation">(</span><span class="token number">9</span><span class="token punctuation">,</span> <span class="token number">17</span><span class="token punctuation">)</span><span class="token punctuation">)</span>         <span class="token comment">// 时：9 点到 17 点之间</span>
                <span class="token punctuation">.</span><span class="token function">withDoM</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string">&quot;*&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span>                <span class="token comment">// 日：每天</span>
                <span class="token punctuation">.</span><span class="token function">withMonth</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string">&quot;*&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span>              <span class="token comment">// 月：每月</span>
                <span class="token punctuation">.</span><span class="token function">withDoW</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">questionMark</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>          <span class="token comment">// 周：不指定</span>
                <span class="token punctuation">.</span><span class="token function">instance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 输出生成的 Cron 表达式</span>
        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;生成的 Cron 表达式: &quot;</span> <span class="token operator">+</span> cron<span class="token punctuation">.</span><span class="token function">asString</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>运行结果：</p><div class="language-text" data-ext="text"><pre class="language-text"><code>生成的 Cron 表达式: 0 0/5 9-17 * * ?
</code></pre></div><hr><h3 id="_4-总结" tabindex="-1"><a class="header-anchor" href="#_4-总结" aria-hidden="true">#</a> 4. <strong>总结</strong></h3><ul><li><strong>替代无参数的 <code>every()</code></strong>： <ul><li>使用 <code>FieldExpressionFactory.on(&quot;*&quot;)</code> 表示“所有值”。</li><li>或使用 <code>FieldExpressionFactory.between(start, end)</code> 表示范围。</li></ul></li><li><strong>字段适配性</strong>： <ul><li>对于秒、分、时字段，仍然需要使用带参数的 <code>every(interval)</code> 方法。</li><li>对于日期（<code>DoM</code>）和月份（<code>Month</code>）字段，使用 <code>on(&quot;*&quot;)</code> 或 <code>between(start, end)</code>。</li></ul></li></ul><p>如果你还有其他疑问或需要进一步优化，请随时补充说明！</p>`,85)]))}const u=s(o,[["render",c],["__file","index.html.vue"]]);export{u as default};
